INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1335506-me438', 'stk-user4626', 'ME 438', 'info', '{"desc": "النوت ما تغير من فترة لكن عليه ابديت\nو طريقة اختيار الهوموركات كالتالي\nمثلا سمستر 121 يقولك حل 2 5 7 و السمستر 122 3 6 8\nطبعا الافكار متشابهة فلو عرفت حل سؤال رقم 2 تلاقيه مايفرق في الفكرة الاساسية عن سؤال 3 مثلا\nفي الجمعية في نسخة من الهوموركات راح تفيدك في كل الحالات\nالمادة هذه الهوموركات فيها جدا جدا مهمة لأنه افكار المياجر ما تطلع منها ابدا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-438-hw-solutions/157677/4", "user": "user4626", "ts": 1393678517000, "tid": 157677, "pn": 4}}', 1393678517000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
